/// Read-only modifier: cap amount to `max(0, 20 - taken_so_far)`.
/// The counter mutation happens in the paired `after_damage_received`
/// handler (Rust's `modify_hp_lost` signature is `&CombatState`, so
/// the accumulator update lives in the post-damage channel).
#[allow(clippy::trivially_copy_pass_by_ref)]
pub(crate) fn on_modify_hp_lost_beating_remnant(
    state: &CombatState,
    ctx: &ModifyHpLostCtx,
    current_amount: i32,
) -> i32 {
    if !player_owns_relic(state, crate::RelicKind::BeatingRemnant) {
        return current_amount;
    }
    if Some(ctx.target) != state.player.creature_uid {
        return current_amount;
    }
    let taken = beating_remnant_counter(state);
    let remaining = (BEATING_REMNANT_MAX_HP_LOSS - taken).max(0);
    current_amount.min(remaining)
}

/// Pair to `on_modify_hp_lost_beating_remnant`: bump `damage_this_turn`
